verify.kernel_code:
pub fn verify(open_surface: bool, secret_set: bool, matches: bool) -> bool {
    if open_surface {
        return true;
    }
    secret_set && matches
}

Watchdog.kernel_code:
pub struct Watchdog {
    pub active: bool,
    pub last_motion_ms: u64,
}

may_acquire.kernel_code:
pub fn may_acquire(held_last_seen: Option<u64>, now_secs: u64) -> bool {
    match held_last_seen {
        None => true,
        Some(last) => {
            let age = if now_secs > last { now_secs - last } else { 0 };
            age > SESSION_TIMEOUT_SECS
        }
    }
}

MotionKind.kernel_code:
pub enum MotionKind {
    /// Not a motion stream or probe command: leaves the watchdog as it is.
    Other,
    /// A motion/probe command asking for zero motion: an explicit stop.
    Stop,
    /// A motion/probe command asking for motion.
    Active,
}

watchdog_on_command.kernel_code:
pub fn watchdog_on_command(w: Watchdog, kind: MotionKind, now_ms: u64) -> Watchdog {
    match kind {
        MotionKind::Active => Watchdog { active: true, last_motion_ms: now_ms },
        MotionKind::Stop => Watchdog { active: false, last_motion_ms: w.last_motion_ms },
        MotionKind::Other => w,
    }
}

watchdog_on_command.lean:
def watchdog_on_command
  (w : Watchdog) (kind : MotionKind) (now_ms : Std.U64) : Result Watchdog := do
  match kind with
  | MotionKind.Other => ok w
  | MotionKind.Stop => ok { w with active := false }
  | MotionKind.Active => ok { active := true, last_motion_ms := now_ms }

watchdog_trip.kernel_code:
pub fn watchdog_trip(w: Watchdog, now_ms: u64) -> (Watchdog, bool) {
    if !w.active {
        return (w, false);
    }
    let age = if now_ms > w.last_motion_ms { now_ms - w.last_motion_ms } else { 0 };
    if age > MOTION_WATCHDOG_MS {
        (Watchdog { active: false, last_motion_ms: w.last_motion_ms }, true)
    } else {
        (w, false)
    }
}

idle_wait.kernel_code:
pub fn idle_wait(next_deadline: u64, now_ms: u64) -> u64 {
    let w = if next_deadline > now_ms { next_deadline - now_ms } else { 0 };
    let w = if w > COMMAND_IDLE_POLL_MS { COMMAND_IDLE_POLL_MS } else { w };
    let w = if w > MOTION_WATCHDOG_POLL_MS { MOTION_WATCHDOG_POLL_MS } else { w };
    if w < 1 { 1 } else { w }
}
